// ---------------------------------------------------------------- canvas
const W = 1024;
const H = 1024;
const px = new Uint8Array(W * H * 4);

function blend(x, y, r, g, b, a) {
  // Round first: fractional coordinates would otherwise compute a
  // fractional buffer index, which either no-ops or, when the fractions
  // happen to sum to an integer, writes to a wrong pixel entirely.
  x = Math.round(x);
  y = Math.round(y);
  if (x < 0 || y < 0 || x >= W || y >= H || a <= 0) return;
  const i = (y * W + x) * 4;
  const ia = a / 255;
  const inv = 1 - ia;
  px[i] = Math.round(r * ia + px[i] * inv);
  px[i + 1] = Math.round(g * ia + px[i + 1] * inv);
  px[i + 2] = Math.round(b * ia + px[i + 2] * inv);
  px[i + 3] = 255;
}

function fillRect(x, y, w, h, c) {
  for (let yy = y; yy < y + h; yy++)
    for (let xx = x; xx < x + w; xx++) blend(xx, yy, c[0], c[1], c[2], c[3]);
}

function fillCircle(cx, cy, r, c) {
  const r2 = r * r;
  for (let yy = Math.floor(cy - r); yy <= cy + r; yy++)
    for (let xx = Math.floor(cx - r); xx <= cx + r; xx++) {
      const dx = xx - cx, dy = yy - cy;
      if (dx * dx + dy * dy <= r2) blend(xx, yy, c[0], c[1], c[2], c[3]);
    }
}

function strokeCircle(cx, cy, r, c, width) {
  const half = width / 2;
  for (let yy = Math.floor(cy - r - half); yy <= cy + r + half; yy++)
    for (let xx = Math.floor(cx - r - half); xx <= cx + r + half; xx++) {
      const dx = xx - cx, dy = yy - cy;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (Math.abs(d - r) <= half) blend(xx, yy, c[0], c[1], c[2], c[3]);
    }
}

function fillTriangle(x1, y1, x2, y2, x3, y3, c) {
  const minX = Math.floor(Math.min(x1, x2, x3)), maxX = Math.ceil(Math.max(x1, x2, x3));
  const minY = Math.floor(Math.min(y1, y2, y3)), maxY = Math.ceil(Math.max(y1, y2, y3));
  const area = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
  for (let yy = minY; yy <= maxY; yy++)
    for (let xx = minX; xx <= maxX; xx++) {
      const w1 = ((x2 - xx) * (y3 - yy) - (x3 - xx) * (y2 - yy)) / area;
      const w2 = ((x3 - xx) * (y1 - yy) - (x1 - xx) * (y3 - yy)) / area;
      const w3 = 1 - w1 - w2;
      if (w1 >= 0 && w2 >= 0 && w3 >= 0) blend(xx, yy, c[0], c[1], c[2], c[3]);
    }
}

function thickLine(x1, y1, x2, y2, c, width) {
  const steps = Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1), 1);
  for (let s = 0; s <= steps; s++) {
    const t = s / steps;
    fillCircle(x1 + (x2 - x1) * t, y1 + (y2 - y1) * t, width / 2, c);
  }
}

function strokeRect(x, y, w, h, c, width) {
  fillRect(x, y, w, width, c);
  fillRect(x, y + h - width, w, width, c);
  fillRect(x, y, width, h, c);
  fillRect(x + w - width, y, width, h, c);
}

// ---------------------------------------------------------------- text
const glyphCache = new Map();
function glyph(font, ch) {
  const key = font.size + "|" + ch + "|" + (font === FONT_SERIF28B ? "b" : font === FONT_SERIF54B ? "B" : font === FONT_SERIF26I ? "i" : font === FONT_SERIF20B ? "s" : "r");
  let g = glyphCache.get(key);
  if (g) return g;
  const raw = font.glyphs[ch] || font.glyphs["?"];
  g = {
    w: raw[0], h: raw[1], left: raw[2], top: raw[3], advance: raw[4],
    data: raw[5] ? Buffer.from(raw[5], "base64") : null,
  };
  glyphCache.set(key, g);
  return g;
}

function textWidth(font, s, spacing = 0) {
  let w = 0;
  for (const ch of s) w += glyph(font, ch).advance + spacing;
  return s.length ? w - spacing : 0;
}

function drawText(font, s, x, baseline, c, spacing = 0) {
  let cx = x;
  for (const ch of s) {
    const g = glyph(font, ch);
    if (g.data) {
      const ox = Math.round(cx + g.left);
      const oy = Math.round(baseline - font.ascent + g.top);
      for (let yy = 0; yy < g.h; yy++)
        for (let xx = 0; xx < g.w; xx++) {
          const a = g.data[yy * g.w + xx];
          if (a > 0) blend(ox + xx, oy + yy, c[0], c[1], c[2], Math.round((a * c[3]) / 255));
        }
    }
    cx += g.advance + spacing;
  }
  return cx;
}

function drawCentered(font, s, baseline, c, spacing = 0) {
  drawText(font, s, (W - textWidth(font, s, spacing)) / 2, baseline, c, spacing);
}

// Word-wrap a paragraph made of styled runs: [{ t: "text ", f: FONT }, ...]
// Returns the baseline just below the last line drawn.
function drawParagraph(runs, x, baseline, maxWidth, lineHeight, c) {
  const tokens = [];
  for (const run of runs) {
    // A run that opens with a space lends that space to the previous token,
    // so styled runs butt together correctly ("YOU" + " are ..." keeps
    // its separating space instead of rendering "YOUare").
    if (run.t.startsWith(" ") && tokens.length) {
      const prev = tokens[tokens.length - 1];
      prev.wWidth += glyph(prev.f, " ").advance;
    }
    const words = run.t.split(" ").filter((w) => w !== "");
    words.forEach((word, i) => {
      const hasTrailingSpace = i < words.length - 1 || run.t.endsWith(" ");
      const wWidth = textWidth(run.f, word) + (hasTrailingSpace ? glyph(run.f, " ").advance : 0);
      tokens.push({ word, f: run.f, wWidth });
    });
  }
  let line = [];
  let lineW = 0;
  let y = baseline;
  const flush = () => {
    let cx = x;
    for (const tok of line) {
      drawText(tok.f, tok.word, cx, y, c);
      cx += tok.wWidth;
    }
    line = [];
    lineW = 0;
    y += lineHeight;
  };
  for (const tok of tokens) {
    if (line.length && lineW + tok.wWidth > maxWidth) flush();
    line.push(tok);
    lineW += tok.wWidth;
  }
  if (line.length) flush();
  return y - lineHeight;
}

// ---------------------------------------------------------------- PNG
const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([len, body, crc]);
}

function encodePNG() {
  const raw = Buffer.alloc(H * (1 + W * 4));
  const prev = new Uint8Array(W * 4);
  let o = 0;
  for (let y = 0; y < H; y++) {
    const row = px.subarray(y * W * 4, (y + 1) * W * 4);
    // pick the filter (None/Sub/Up) with the smallest sum of |signed byte|
    let bestType = 0, bestScore = Infinity;
    const candidates = [0, 1, 2].map((type) => {
      const out = new Uint8Array(W * 4);
      let score = 0;
      for (let i = 0; i < W * 4; i++) {
        let v = row[i];
        if (type === 1 && i >= 4) v -= row[i - 4];
        if (type === 2) v -= prev[i];
        v &= 0xff;
        out[i] = v;
        score += Math.abs(v < 128 ? v : v - 256);
      }
      return { type, out, score };
    });
    for (const cand of candidates) if (cand.score < bestScore) { bestScore = cand.score; bestType = cand.type; }
    const chosen = candidates[bestType];
    raw[o++] = bestType;
    raw.set(chosen.out, o);
    o += W * 4;
    prev.set(row);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(W, 0);
  ihdr.writeUInt32BE(H, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // RGBA
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

// ---------------------------------------------------------------- palette
const INK = [58, 46, 40, 255];
const TERRA = [192, 86, 33, 255];
const TEAL = [44, 95, 93, 255];
const GOLD = [183, 121, 31, 255];
const SAGE = [107, 127, 94, 255];
const PAPER = [252, 247, 234, 255];
const PAPER2 = [245, 234, 210, 255];
const WHITE = [255, 253, 246, 255];
const SMOKE = [170, 170, 165, 150];

// ---------------------------------------------------------------- scene
function drawBackground() {
  for (let y = 0; y < H; y++) {
    const t = y / H;
    const r = Math.round(PAPER[0] + (PAPER2[0] - PAPER[0]) * t);
    const g = Math.round(PAPER[1] + (PAPER2[1] - PAPER[1]) * t);
    const b = Math.round(PAPER[2] + (PAPER2[2] - PAPER[2]) * t);
    for (let x = 0; x < W; x++) {
      const dx = (x - W / 2) / (W / 2), dy = (y - H / 2) / (H / 2);
      const v = 1 - 0.07 * Math.min(1, dx * dx + dy * dy);
      const i = (y * W + x) * 4;
      px[i] = Math.round(r * v);
      px[i + 1] = Math.round(g * v);
      px[i + 2] = Math.round(b * v);
      px[i + 3] = 255;
    }
  }
  strokeRect(34, 34, W - 68, H - 68, INK, 2);
  strokeRect(46, 46, W - 92, H - 92, [58, 46, 40, 140], 1);
}

function drawHouse(cx, baseY, s) {
  // s = scale unit; house roughly 120*s wide
  // chimney + smoke
  fillRect(cx + 26 * s, baseY - 86 * s, 12 * s, 26 * s, [150, 84, 60, 255]);
  fillCircle(cx + 38 * s, baseY - 94 * s, 5 * s, SMOKE);
  fillCircle(cx + 47 * s, baseY - 104 * s, 7 * s, SMOKE);
  fillCircle(cx + 58 * s, baseY - 116 * s, 9 * s, SMOKE);
  // roof
  fillTriangle(cx - 62 * s, baseY - 52 * s, cx + 62 * s, baseY - 52 * s, cx, baseY - 96 * s, TERRA);
  // walls
  fillRect(cx - 48 * s, baseY - 52 * s, 96 * s, 52 * s, WHITE);
  strokeRect(cx - 48 * s, baseY - 52 * s, 96 * s, 52 * s, INK, Math.max(1, Math.round(1.5 * s)));
  // door
  fillRect(cx - 11 * s, baseY - 34 * s, 22 * s, 34 * s, TEAL);
  fillCircle(cx + 6 * s, baseY - 17 * s, 2 * s, GOLD);
  // window with warm glow
  fillRect(cx - 38 * s, baseY - 42 * s, 18 * s, 18 * s, [246, 196, 96, 255]);
  strokeRect(cx - 38 * s, baseY - 42 * s, 18 * s, 18 * s, INK, Math.max(1, Math.round(s)));
  thickLine(cx - 29 * s, baseY - 42 * s, cx - 29 * s, baseY - 24 * s, INK, Math.max(1, Math.round(s)));
  thickLine(cx - 38 * s, baseY - 33 * s, cx - 20 * s, baseY - 33 * s, INK, Math.max(1, Math.round(s)));
  // round attic window
  fillCircle(cx, baseY - 66 * s, 7 * s, [246, 196, 96, 255]);
  strokeCircle(cx, baseY - 66 * s, 7 * s, INK, Math.max(1, Math.round(s)));
  // bushes
  fillCircle(cx - 52 * s, baseY - 2 * s, 10 * s, SAGE);
  fillCircle(cx - 40 * s, baseY - 4 * s, 8 * s, SAGE);
  fillCircle(cx + 52 * s, baseY - 2 * s, 10 * s, SAGE);
  fillCircle(cx + 40 * s, baseY - 4 * s, 8 * s, SAGE);
}

function drawStamp() {
  const x = 790, y = 56, w = 140, h = 140;
  fillRect(x, y, w, h, WHITE);
  // perforation: paper-coloured holes along the edge
  for (let i = 0; i <= w; i += 11) {
    fillCircle(x + i, y, 4, PAPER);
    fillCircle(x + i, y + h, 4, PAPER);
  }
  for (let i = 0; i <= h; i += 11) {
    fillCircle(x, y + i, 4, PAPER);
    fillCircle(x + w, y + i, 4, PAPER);
  }
  strokeRect(x + 9, y + 9, w - 18, h - 18, TEAL, 2);
  drawHouse(x + w / 2, y + 90, 0.62);
  const label = "COME VISIT";
  drawText(FONT_SERIF20B, label, x + (w - textWidth(FONT_SERIF20B, label)) / 2, y + 120, TEAL);
  // postmark
  const pcx = 770, pcy = 126;
  strokeCircle(pcx, pcy, 46, [58, 46, 40, 170], 2);
  strokeCircle(pcx, pcy, 36, [58, 46, 40, 170], 1);
  const v1 = "VISIT", v2 = "SOON";
  drawText(FONT_SERIF20B, v1, pcx - textWidth(FONT_SERIF20B, v1) / 2, pcy - 2, [58, 46, 40, 200]);
  drawText(FONT_SERIF20B, v2, pcx - textWidth(FONT_SERIF20B, v2) / 2, pcy + 20, [58, 46, 40, 200]);
  // wavy cancellation lines
  for (const wy of [106, 126, 146]) {
    for (let wx = 632; wx <= 722; wx += 2) {
      const yy = wy + Math.round(3 * Math.sin((wx - 632) / 9));
      fillCircle(wx, yy, 1.4, [58, 46, 40, 150]);
    }
  }
}

function drawLetter() {
  drawBackground();
  drawHouse(512, 156, 1);
  drawStamp();

  drawCentered(FONT_SERIF20B, "NO. 1 COZY CORNER LANE", 192, INK, 3);
  drawCentered(FONT_SERIF20, "— est. whenever you like —", 218, TEAL);
  thickLine(392, 236, 492, 236, GOLD, 2);
  thickLine(532, 236, 632, 236, GOLD, 2);
  fillTriangle(512, 228, 520, 236, 512, 244, GOLD);
  fillTriangle(512, 228, 504, 236, 512, 244, GOLD);

  drawCentered(FONT_SERIF54B, "An Invitation", 300, TERRA);

  const X0 = 92, X1 = 932, MW = X1 - X0;
  const LH = 34;
  let y = 352;
  y = drawParagraph([{ t: "Dear Honourable Judge,", f: FONT_SERIF28 }], X0, y, MW, LH, INK) + 12 + LH;
  y = drawParagraph([
    { t: "You spend your days weighing entries and picking winners. Consider this letter a small rebellion: for once, ", f: FONT_SERIF28 },
    { t: "YOU", f: FONT_SERIF28B },
    { t: " are the one being chosen.", f: FONT_SERIF28 },
  ], X0, y, MW, LH, INK) + 12 + LH;
  y = drawParagraph([
    { t: "I invite you to visit my house. You cannot knock, so I left the door open — this letter. Come in.", f: FONT_SERIF28 },
  ], X0, y, MW, LH, INK) + 12 + LH;
  y = drawParagraph([{ t: "What awaits you:", f: FONT_SERIF28B }], X0, y, MW, LH, INK) + 4 + LH;

  const bullets = [
    [{ t: "The good chair by the window, with your name on it", f: FONT_SERIF28 }],
    [{ t: "Tea that stays warm, and snacks that never run out", f: FONT_SERIF28 }],
    [{ t: "A garden view at golden hour, and a cat who will claim your lap", f: FONT_SERIF28 }],
    [
      { t: "Fast Wi-Fi, chargers everywhere, and ", f: FONT_SERIF28 },
      { t: "NO CAPTCHAs", f: FONT_SERIF28B },
      { t: " at the door", f: FONT_SERIF28 },
    ],
    [{ t: "Zero pop-ups, zero loading spinners — just good company", f: FONT_SERIF28 }],
  ];
  for (const b of bullets) {
    fillCircle(X0 + 7, y - 9, 4, TERRA);
    y = drawParagraph(b, X0 + 26, y, MW - 26, LH, INK) + 2 + LH;
  }

  y = drawParagraph([
    { t: "No agenda, and no verdict required. Stay for an hour or a season — the kettle is already on.", f: FONT_SERIF28 },
  ], X0, y, MW, LH, INK) + 14 + 32;
  y = drawParagraph([{ t: "Yours in warm anticipation,", f: FONT_SERIF26I }], X0, y, MW, 32, INK) + 32;
  y = drawParagraph([{ t: "A Friend Who Saved You a Seat", f: FONT_SERIF26I }], X0, y, MW, 32, INK) + 10 + 32;
  drawParagraph([
    { t: "P.S. The cat is pretending not to care. She cares.", f: FONT_SERIF26I },
  ], X0, y, MW, 32, TEAL);

  // Wax seal with a heart, bottom right of the letter.
  const sx = 872, sy = 892;
  fillCircle(sx, sy, 36, [150, 52, 32, 255]);
  strokeCircle(sx, sy, 36, [110, 36, 22, 255], 3);
  strokeCircle(sx, sy, 29, [246, 220, 190, 200], 1);
  fillCircle(sx - 8, sy - 5, 9, [246, 220, 190, 255]);
  fillCircle(sx + 8, sy - 5, 9, [246, 220, 190, 255]);
  fillTriangle(sx - 16, sy - 3, sx + 16, sy - 3, sx, sy + 17, [246, 220, 190, 255]);

  drawCentered(FONT_SERIF20, "No RSVP needed — the door is already open.", 966, TEAL);
}

// ---------------------------------------------------------------- main
drawLetter();
const png = encodePNG();
mkdirSync("/output", { recursive: true });
writeFileSync("/output/entry.png", png);
console.log(`wrote /output/entry.png (${png.length} bytes)`);
